btnAction = "Insert";
$("#modal-class").on("submit", function(e) {
    e.preventDefault();

    
    const formElement = $(this).is("form") ? $(this)[0] : $(this).find("form")[0];

    if (!formElement) {
        console.error("No form element found within #modal-class");
        return;
    }

  
    let fromdate = new FormData(formElement);
    fromdate.append("image", $("input[type=file]")[0]?.files[0]); 

   
    if (btnAction === "Insert") {
        fromdate.append("action", "Register_student");
    } else 
   // if (btnAction === "update") 
    {  
        const studentId = $("#update_id").val(); 
        fromdate.append("action", "update_student");
        fromdate.append("student_id", studentId); 
         
    }

    $.ajax({ 
        type: "POST",
        url: "../Api/studentview.php",
        data: fromdate,
        dataType: "json",
        processData: false,
        contentType: false,
        success: function(response) {
            // let status = data.status;
            // let response = data.data;
            // console.log(response.error);

            if (response.status = "success") {
                Swal.fire({
                    title: response.data,
                    icon: "success"
                });
                loadData();
                $('#student_from')[0].reset();
                btnAction = "Insert";
            } else if (response.status = "error") {
                // console.log(response);
                Swal.fire({
                    title: response.data,
                    icon: "error"
                });
            }
        },
        error: function(data) {
            console.log("error", data);
        }
    });
});










//   search student nnames
$(document).ready(function () {
    $('#search-bar').on('input', function () {
        let searchQuery = $(this).val();  

       
        $.ajax({
            type: 'GET',
            url: '../Api/search.php',
            data: { search: searchQuery },
            dataType: 'json',
            success: function (data) {
                updateStudentTable(data); 
            },
            error: function () {
                alert('Error fetching data.');
            }
        });
    });
});


function updateStudentTable(students) {
    let tableBody = $('#student_table tbody');
    tableBody.empty();  

    if (students.length > 0) {
        students.forEach(function(student, index) {
            let row = `
                <tr>
                    <td>${index + 1}</td>
                    <td>${student.first_name} ${student.last_name}</td>
                    <td>${student.Gender}</td>
                    <td>${student.email}</td>
                     <td>${student.department_name}</td>
                    <td>${student.class_name}</td>
                    <td>${student.contact_number}</td>
                    <td>
                      
                        &nbsp;&nbsp;
                        <a class="updete_cl" update_id="${student.student_id}">
                            <span class="material-symbols-outlined" style="color:#fff;background-color:blue;font-size: xx-large;font-weight: bold;border-radius: 5px;">edit</span>
                        </a>
                        &nbsp;&nbsp;
                        <a class="delete_cl" delete_id="${student.student_id}">
                            <span class="material-symbols-outlined" style="color:#fff;background-color:red;font-size: xx-large;font-weight: bold;border-radius: 5px;">delete</span>
                        </a>
                    </td>
                </tr>
            `;
            tableBody.append(row);
        });
    } else {
        tableBody.append('<tr><td colspan="6">No students found</td></tr>');
    }
}





loadData();
function loadData(){

    $("#student_table tbody").html('');

    let sendingData = {
        "action" : "student_table"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url: "../Api/studentview.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

          

             if(status){

                response.forEach( itm => {

                    tr += "<tr>";
                    for(let i in itm){

                      
                            tr += `<td>${itm[i]}</td>`;
                        }
                       
                    

                        tr += `<td >
                      
                        &nbsp;&nbsp; <buttonclass="btn_upda"> <a class="updete_cl"update_id=${itm['student_id']}><span class="material-symbols-outlined" style ="color:#fff;background-color:blue; font-size: xx-large;  font-weight: bold; border-radius: 5px; ">edit
                        </span></a></button> &nbsp;&nbsp;<a class="delete_cl" delete_id=${itm['student_id']}><span class="material-symbols-outlined" style ="color:#fff;background-color:red;font-size: xx-large;  font-weight: bold; border-radius: 5px;">delete
                        </span></a> </td>` 
                       
                        tr += '</tr>'  

                })

                $("#student_table tbody").append(tr);

            }else{
                console.log("error",response);
            }
           

        },
        error: function(data){
            console.log(data);

        }
    })

}

